 1→import { Module, DynamicModule } from '@nestjs/common';
 2→import { ConfigModule, ConfigService } from '@nestjs/config';
 3→import { IPFS_PROVIDER, LocalProvider } from './providers';
 4→import { IpfsController } from './ipfs.controller';
 5→import { VaultModule } from '../vault/vault.module';
 6→
 7→@Module({})
 8→export class IpfsModule {
 9→  static forRootAsync(): DynamicModule {
10→    return {
11→      module: IpfsModule,
12→      imports: [ConfigModule, VaultModule],
13→      controllers: [IpfsController],
14→      providers: [
15→        {
16→          provide: IPFS_PROVIDER,
17→          useFactory: (configService: ConfigService) => {
18→            const apiUrl = configService.get<string>('IPFS_LOCAL_API_URL', 'http://localhost:5001');
19→            const gatewayUrl = configService.get<string>(
20→              'IPFS_LOCAL_GATEWAY_URL',
21→              'http://localhost:8080'
22→            );
23→            return new LocalProvider(apiUrl, gatewayUrl);
24→          },
25→          inject: [ConfigService],
26→        },
27→      ],
28→      exports: [IPFS_PROVIDER],
29→    };
30→  }
31→}
