 1→/**
 2→ * Mock Delegated Routing Service for E2E Testing
 3→ *
 4→ * Implements the IPFS delegated routing API for IPNS records:
 5→ * - PUT /routing/v1/ipns/{name} - Store an IPNS record
 6→ * - GET /routing/v1/ipns/{name} - Retrieve an IPNS record
 7→ *
 8→ * Records are stored in-memory and reset when the service restarts.
 9→ * This allows E2E tests to run without polluting the public IPFS DHT
10→ * and avoids sequence number conflicts from repeated test runs.
11→ */
12→import Fastify from 'fastify';
13→const fastify = Fastify({
14→    logger: {
15→        level: process.env.LOG_LEVEL ?? 'info',
16→        transport: process.env.NODE_ENV !== 'production'
17→            ? { target: 'pino-pretty', options: { colorize: true } }
18→            : undefined,
19→    },
20→});
21→// In-memory storage for IPNS records
22→// Key: IPNS name (k51... or bafzaa...), Value: raw record bytes
23→const ipnsRecords = new Map();
24→// Health check endpoint
25→fastify.get('/health', async () => {
26→    return { status: 'ok', records: ipnsRecords.size };
27→});
28→// GET /routing/v1/ipns/{name} - Retrieve IPNS record
29→fastify.get('/routing/v1/ipns/:name', async (request, reply) => {
30→    const { name } = request.params;
31→    const record = ipnsRecords.get(name);
32→    if (!record) {
33→        return reply.status(404).send({
34→            error: 'record not found',
35→            name,
36→        });
37→    }
38→    fastify.log.info({ name, size: record.length }, 'Retrieved IPNS record');
39→    return reply.status(200).header('Content-Type', 'application/vnd.ipfs.ipns-record').send(record);
40→});
41→// PUT /routing/v1/ipns/{name} - Store IPNS record
42→fastify.put('/routing/v1/ipns/:name', async (request, reply) => {
43→    const { name } = request.params;
44→    // Get raw body as Buffer
45→    const body = request.body;
46→    if (!body || body.length === 0) {
47→        return reply.status(400).send({
48→            error: 'empty request body',
49→        });
50→    }

